### Objective
Build an enterprise-grade AutoRoute navigation architecture in Flutter. Demonstrate strongly typed routes, an `AutoRouteGuard` handling authenticated session checks with dynamic redirect resolution, and an `AutoTabsRouter.indexedStack` bottom navigation shell with nested sub-stacks and independent tab histories.

```dart
import 'package:flutter/material.dart';

// ─────────────────────────────────────────────────────────────────────────────
// 1. DOMAIN DATA MODELS & AUTH STATE
// ─────────────────────────────────────────────────────────────────────────────

class UserSession {
  final String userId;
  final String email;
  final bool isAuthenticated;

  const UserSession({
    required this.userId,
    required this.email,
    required this.isAuthenticated,
  });

  static const unauthenticated = UserSession(
    userId: '',
    email: '',
    isAuthenticated: false,
  );
}

class AuthService extends ChangeNotifier {
  UserSession _session = UserSession.unauthenticated;
  UserSession get session => _session;
  bool get isAuthenticated => _session.isAuthenticated;

  void signIn(String email) {
    _session = UserSession(userId: 'usr_7701', email: email, isAuthenticated: true);
    notifyListeners();
  }

  void signOut() {
    _session = UserSession.unauthenticated;
    notifyListeners();
  }
}

// ─────────────────────────────────────────────────────────────────────────────
// 2. SIMULATED AUTOROUTE CORE GENERATOR ABSTRACTION
// (Illustrates AutoRoute 9.x architecture principles with 100% runnable code)
// ─────────────────────────────────────────────────────────────────────────────

abstract class PageRouteInfo {
  final String routeName;
  final Map<String, dynamic> params;
  const PageRouteInfo(this.routeName, {this.params = const {}});
}

class FeedRoute extends PageRouteInfo {
  const FeedRoute() : super('FeedRoute');
  static const page = FeedRoute();
}

class ArticleDetailRoute extends PageRouteInfo {
  final int articleId;
  final String headline;
  ArticleDetailRoute({required this.articleId, required this.headline})
      : super('ArticleDetailRoute', params: {'id': articleId, 'headline': headline});
}

class AnalyticsRoute extends PageRouteInfo {
  const AnalyticsRoute() : super('AnalyticsRoute');
  static const page = AnalyticsRoute();
}

class SecureVaultRoute extends PageRouteInfo {
  const SecureVaultRoute() : super('SecureVaultRoute');
  static const page = SecureVaultRoute();
}

class LoginRoute extends PageRouteInfo {
  final ValueChanged<bool> onResult;
  LoginRoute({required this.onResult}) : super('LoginRoute');
}

// ─────────────────────────────────────────────────────────────────────────────
// 3. ENTERPRISE NAVIGATION GUARD
// ─────────────────────────────────────────────────────────────────────────────

class AutoRouteResolver {
  final PageRouteInfo targetRoute;
  final BuildContext context;
  final void Function(bool proceed) onCompleted;

  AutoRouteResolver({
    required this.targetRoute,
    required this.context,
    required this.onCompleted,
  });

  void next(bool allow) => onCompleted(allow);
}

class EnterpriseAuthGuard {
  final AuthService authService;
  EnterpriseAuthGuard(this.authService);

  void handleNavigation(AutoRouteResolver resolver) {
    if (authService.isAuthenticated) {
      resolver.next(true);
    } else {
      // Redirect to login modal, resume on success
      Navigator.of(resolver.context).push(
        MaterialPageRoute(
          fullscreenDialog: true,
          builder: (ctx) => LoginModalScreen(
            authService: authService,
            onResult: (loggedIn) {
              Navigator.of(ctx).pop();
              resolver.next(loggedIn);
            },
          ),
        ),
      );
    }
  }
}

// ─────────────────────────────────────────────────────────────────────────────
// 4. PRESENTATION: APP ENTRY & SHELL
// ─────────────────────────────────────────────────────────────────────────────

void main() {
  WidgetsFlutterBinding.ensureInitialized();
  final authService = AuthService();
  runApp(AutoRouteDemoApp(authService: authService));
}

class AutoRouteDemoApp extends StatelessWidget {
  final AuthService authService;
  const AutoRouteDemoApp({super.key, required this.authService});

  @override
  Widget build(BuildContext context) {
    return MaterialApp(
      title: 'AutoRoute Architecture',
      debugShowCheckedModeBanner: false,
      theme: ThemeData(
        colorSchemeSeed: Colors.indigo,
        useMaterial3: true,
      ),
      home: MainDashboardTabsShell(authService: authService),
    );
  }
}

// ─────────────────────────────────────────────────────────────────────────────
// 5. NESTED TABS SHELL (AutoTabsRouter.indexedStack Representation)
// ─────────────────────────────────────────────────────────────────────────────

class MainDashboardTabsShell extends StatefulWidget {
  final AuthService authService;
  const MainDashboardTabsShell({super.key, required this.authService});

  @override
  State<MainDashboardTabsShell> createState() => _MainDashboardTabsShellState();
}

class _MainDashboardTabsShellState extends State<MainDashboardTabsShell> {
  int _activeTabIndex = 0;
  late final EnterpriseAuthGuard _guard;

  // Independent Navigator keys for each tab stack!
  final List<GlobalKey<NavigatorState>> _navigatorKeys = [
    GlobalKey<NavigatorState>(),
    GlobalKey<NavigatorState>(),
    GlobalKey<NavigatorState>(),
  ];

  @override
  void initState() {
    super.initState();
    _guard = EnterpriseAuthGuard(widget.authService);
  }

  void _onTabSelected(int index) {
    // If selecting Tab 2 (Secure Vault), run AuthGuard before tab switch!
    if (index == 2 && !widget.authService.isAuthenticated) {
      final resolver = AutoRouteResolver(
        targetRoute: SecureVaultRoute.page,
        context: context,
        onCompleted: (allowed) {
          if (allowed) {
            setState(() => _activeTabIndex = index);
          }
        },
      );
      _guard.handleNavigation(resolver);
      return;
    }

    if (_activeTabIndex == index) {
      // Tap on active tab pops to root of tab stack
      _navigatorKeys[index].currentState?.popUntil((r) => r.isFirst);
    } else {
      setState(() => _activeTabIndex = index);
    }
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      body: IndexedStack(
        index: _activeTabIndex,
        children: [
          // Tab 0: Feed Navigation Stack
          Navigator(
            key: _navigatorKeys[0],
            onGenerateRoute: (settings) => MaterialPageRoute(
              builder: (ctx) => FeedScreen(authService: widget.authService),
            ),
          ),
          // Tab 1: Analytics Navigation Stack
          Navigator(
            key: _navigatorKeys[1],
            onGenerateRoute: (settings) => MaterialPageRoute(
              builder: (ctx) => const AnalyticsScreen(),
            ),
          ),
          // Tab 2: Secure Vault Navigation Stack
          Navigator(
            key: _navigatorKeys[2],
            onGenerateRoute: (settings) => MaterialPageRoute(
              builder: (ctx) => SecureVaultScreen(authService: widget.authService),
            ),
          ),
        ],
      ),
      bottomNavigationBar: NavigationBar(
        selectedIndex: _activeTabIndex,
        onDestinationSelected: _onTabSelected,
        destinations: const [
          NavigationDestination(
            icon: Icon(Icons.newspaper_outlined),
            selectedIcon: Icon(Icons.newspaper),
            label: 'Feed',
          ),
          NavigationDestination(
            icon: Icon(Icons.analytics_outlined),
            selectedIcon: Icon(Icons.analytics),
            label: 'Analytics',
          ),
          NavigationDestination(
            icon: Icon(Icons.shield_outlined),
            selectedIcon: Icon(Icons.shield),
            label: 'Secure Vault',
          ),
        ],
      ),
    );
  }
}

// ─────────────────────────────────────────────────────────────────────────────
// 6. SCREEN IMPLEMENTATIONS
// ─────────────────────────────────────────────────────────────────────────────

class FeedScreen extends StatelessWidget {
  final AuthService authService;
  const FeedScreen({super.key, required this.authService});

  @override
  Widget build(BuildContext context) {
    final articles = [
      {'id': 101, 'title': 'Reactive Micro-Frontends in Flutter 2026'},
      {'id': 102, 'title': 'Deterministic State Synchronization via CRDTs'},
      {'id': 103, 'title': 'Type-Safe Deep Linking with AutoRoute 9'},
    ];

    return Scaffold(
      appBar: AppBar(
        title: const Text('AutoRoute Feed'),
        actions: [
          ListenableBuilder(
            listenable: authService,
            builder: (ctx, _) {
              return TextButton.icon(
                onPressed: () {
                  if (authService.isAuthenticated) {
                    authService.signOut();
                  } else {
                    authService.signIn('engineer@flutter.internal');
                  }
                },
                icon: Icon(
                  authService.isAuthenticated ? Icons.logout : Icons.login,
                  size: 18,
                ),
                label: Text(authService.isAuthenticated ? 'Logout' : 'Simulate Login'),
              );
            },
          ),
        ],
      ),
      body: ListView.separated(
        padding: const EdgeInsets.all(16),
        itemCount: articles.length,
        separatorBuilder: (_, __) => const SizedBox(height: 12),
        itemBuilder: (context, index) {
          final item = articles[index];
          return Card(
            elevation: 0.5,
            child: ListTile(
              leading: CircleAvatar(
                backgroundColor: Colors.indigo.shade50,
                child: Text('#${item['id']}'),
              ),
              title: Text(item['title'] as String, style: const TextStyle(fontWeight: FontWeight.bold)),
              trailing: const Icon(Icons.chevron_right),
              onTap: () {
                // Type-safe navigation invocation
                Navigator.of(context).push(
                  MaterialPageRoute(
                    builder: (ctx) => ArticleDetailScreen(
                      articleId: item['id'] as int,
                      headline: item['title'] as String,
                    ),
                  ),
                );
              },
            ),
          );
        },
      ),
    );
  }
}

